import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] head = new int[n];
        Arrays.fill(head, -1);
        int[] to = new int[2 * m];
        int[] next = new int[2 * m];
        int[] degree = new int[n];

        int edgeIndex = 0;
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;

            to[edgeIndex] = v;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;
            degree[u]++;

            to[edgeIndex] = u;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;
            degree[v]++;
        }

        boolean[] visited = new boolean[n];
        int[] queue = new int[n];
        int[] mark = new int[n];
        int tail = 0;

        for (int root = 0; root < n; root++) {
            if (visited[root]) continue;

            int start = tail;
            queue[tail++] = root;
            visited[root] = true;

            int front = start;
            while (front < tail) {
                int u = queue[front++];
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (!visited[v]) {
                        visited[v] = true;
                        queue[tail++] = v;
                    }
                }
            }

            int componentSize = tail - start;
            for (int i = start; i < tail; i++) {
                int u = queue[i];
                if (degree[u] < componentSize - 1) {
                    int token = u + 1;
                    for (int e = head[u]; e != -1; e = next[e]) {
                        mark[to[e]] = token;
                    }

                    for (int j = start; j < tail; j++) {
                        int v = queue[j];
                        if (v != u && mark[v] != token) {
                            System.out.println((u + 1) + " " + (v + 1));
                            return;
                        }
                    }
                }
            }
        }

        System.out.println(-1);
    }
}
